/* small view helpers */
function x2Card(title, sub, body, right, cls){ return '<section class="a2-card' + (cls ? ' ' + cls : '') + '"><div class="a2-ch"><div><h2 class="a2-h3">' + title + '</h2>' + (sub ? '<div class="a2-cs">' + sub + '</div>' : '') + '</div>' + (right || '') + '</div>' + body + '</section>'; }
function x2Sub(items, active){ return '<nav class="a2-views x2-sub" aria-label="' + Le('Sub pages', 'ভেতরের পাতা') + '">' + items.map(function(t){ var on = t[0] === active; return '<a class="a2-view' + (on ? ' on' : '') + '" href="#' + t[0] + '"' + (on ? ' aria-current="page"' : '') + '>' + Le(t[1], t[2]) + (t[3] ? '<span class="a2-cnt">' + t[3] + '</span>' : '') + '</a>'; }).join('') + '</nav>'; }
function x2Pill(tone, txt){ return '<span class="a2-pill ' + (tone || '') + '">' + txt + '</span>'; }
function x2KV(pairs){ return '<div class="a2-kv2">' + pairs.map(function(p){ return '<span>' + p[0] + '</span><span>' + p[1] + '</span>'; }).join('') + '</div>'; }
function x2Note(html, tone){ return '<div class="a2-note' + (tone ? ' ' + tone : '') + '">' + a2i(tone === 'warn' || tone === 'bad' ? 'alert' : 'help', 15) + '<span>' + html + '</span></div>'; }
function x2Btn(act, en, bn, o){ o = o || {}; return '<button type="button" class="a2-btn' + (o.cls ? ' ' + o.cls : '') + '" data-act="' + act + '"' + (o.attrs || '') + (o.dis ? ' disabled' : '') + '>' + (o.ic ? a2i(o.ic, 15) : '') + Le(en, bn) + '</button>'; }
function x2Lnk(href, en, bn, o){ o = o || {}; return '<a class="a2-btn' + (o.cls ? ' ' + o.cls : '') + '" href="' + href + '">' + (o.ic ? a2i(o.ic, 15) : '') + Le(en, bn) + '</a>'; }
function x2Done(en, bn, ref){ a2Log(en, ref); saveState(); rerender(); toast(L(en, bn)); }
function x2Sw(on, act, attrs, label){ return a2Sw(on, act, attrs, label); }
function x2Empty(t, s, action, icon){ return a2State('empty', {t:t, s:s, action:action || '', icon:icon || 'box'}); }
function x2AIoff(){ return !(ST.ai && ST.ai.master); }
function x2Phone(){ var w = innerWidth || 1366; return w < 768; }
ACT['x2-soon'] = function(el){ toast(L('Demo: “', 'ডেমো: “') + (el.getAttribute('data-t') || '') + L('” runs as a job in the real build — you get a notification when it is done', '” আসল সাইটে কাজ হিসেবে চলবে, শেষ হলে নোটিফিকেশন আসবে')); };

/* ---------- product facts (the ERP mirror; drafts live in the new admin's store) ---------- */
function x2Prod(id){ var p = P(id); if(p) return {id:p.id, p:p, draft:false}; var d = (x2S().drafts || []).filter(function(z){ return z.id === id; })[0]; return d ? {id:d.id, p:d, draft:true} : null; }
function x2Rows(){ var x = x2S(); return (x.drafts || []).map(function(d){ return {id:d.id, p:d, draft:true}; }).concat(DB.products.map(function(p){ return {id:p.id, p:p, draft:false}; })); }
function x2Stock(r){ if(r.draft) return r.p.stock || 0; var p = r.p, f = stockOf._erp || stockOf, t = 0; (p.colors || []).forEach(function(c){ (p.sizes || []).forEach(function(z){ t += f(p.id, c, z); }); }); return t; }
function x2Sellable(p){ var t = 0; (p.colors || []).forEach(function(c){ (p.sizes || []).forEach(function(z){ t += stockOf(p.id, c, z); }); }); return t; }
function x2Price(r){ return r.draft ? r.p.erpPrice : r.p.price; }
function x2CostOf(r){ if(r.draft) return r.p.erpCost; var c = a2Cost(r.p.id); return c == null ? null : c; }
function x2Photos(r){ return r.draft ? r.p.photos || 0 : Math.max(zp_photoCount(r.p), 4); }
function x2Checks(r){
  var p = r.p, ch = CHART(p.chart), sizes = p.sizes || [], cov = ch ? sizes.filter(function(s){ return !ch.rows[s]; }) : sizes;
  var acc = CAT(p.cat) && CAT(p.cat).group === 'acc';
  return [
    {k:'photos', ok:x2Photos(r) >= a2Set('products.minPhotos'), en:x2Photos(r) + ' of ' + a2Set('products.minPhotos') + ' photos', bn:'ছবি ' + x2Photos(r) + '/' + a2Set('products.minPhotos')},
    {k:'chart', ok:acc || (!!ch && !cov.length), en:acc ? 'No size chart needed' : !ch ? 'No size chart' : cov.length ? 'Size chart misses ' + cov.join(', ') : 'Size chart covers every size', bn:!ch && !acc ? 'সাইজ চার্ট নেই' : cov.length && !acc ? 'চার্টে নেই: ' + cov.join(', ') : 'সাইজ চার্ট ঠিক আছে'},
    {k:'stock', ok:x2Stock(r) > 0, en:x2Stock(r) > 0 ? x2Stock(r) + ' pieces in the ERP' : 'No stock in the ERP', bn:x2Stock(r) > 0 ? 'ERP-তে ' + x2Stock(r) + ' পিস' : 'ERP-তে স্টক নেই'},
    {k:'fabric', ok:!!p.fabric, en:p.fabric ? 'Fabric & care written' : 'No fabric note', bn:p.fabric ? 'কাপড়ের তথ্য আছে' : 'কাপড়ের তথ্য নেই'},
    {k:'text', ok:String(p.desc || '').length >= 40, en:String(p.desc || '').length >= 40 ? 'Description written' : 'Description too short', bn:String(p.desc || '').length >= 40 ? 'বর্ণনা আছে' : 'বর্ণনা ছোট'},
    {k:'erp', ok:x2Price(r) > 0 && x2CostOf(r) != null, en:!(x2Price(r) > 0) ? 'Price missing from ERP' : x2CostOf(r) == null ? 'Cost missing from ERP' : 'ERP price and cost synced', bn:!(x2Price(r) > 0) ? 'ERP-তে দাম নেই' : x2CostOf(r) == null ? 'ERP-তে খরচ নেই' : 'ERP-র দাম আর খরচ এসেছে'}];
}
function x2Health(r){ var c = x2Checks(r); return Math.round(c.filter(function(z){ return z.ok; }).length / c.length * 100); }
function x2PState(r){ var o = x2S().pst[r.id]; if(o) return o; if(r.draft) return x2Checks(r).every(function(c){ return c.ok; }) ? 'ready' : 'draft'; return x2Stock(r) > 0 ? 'onsale' : 'oos'; }
var X2_PST = {onsale:['On sale', 'বিক্রি চলছে', 'ok'], ready:['Ready', 'তৈরি', 'g'], draft:['Draft', 'খসড়া', 'line'], unpublished:['Unpublished', 'বন্ধ', 'warn'], oos:['Out of stock', 'স্টক নেই', 'bad'], archived:['Archived', 'আর্কাইভ', 'line']};
function x2PSPill(r){ var s = X2_PST[x2PState(r)]; return x2Pill(s[2], Le(s[0], s[1])); }
function x2Thumb(r, color){ if(!r.draft) return a2Thumb(r.p.id, color); var hex = COL(color || (r.p.colors || [])[0]).hex || '#999', lt = typeof isLight === 'function' && /^#[0-9a-f]{6}$/i.test(hex) && isLight(hex); return '<span class="a2-thumb' + (lt ? ' x2-lt' : '') + '" style="background:' + hex + '">' + a2i('shirt', 18) + '</span>'; }
function x2HScore(n){ return '<span class="x2-hs ' + (n >= 100 ? 'ok' : n >= 67 ? 'warn' : 'bad') + '" title="' + Le('Health score', 'হেলথ স্কোর') + '">' + n + '</span>'; }
function x2Sync(){ var t = x2S().syncAt || (Date.now() - 23 * 60000); return t; }
function x2Sku(pid, c, s){ return 'EX-' + String(pid).replace(/[^a-z]/gi, '').slice(0, 5).toUpperCase() + '-' + String(c).slice(0, 3).toUpperCase() + '-' + s; }

