function x2Reviews(){ var x = x2S(); if(!x.revs){ var base = (DB.reviews || []).map(function(r){ return Object.assign({}, r); }); var extra = [['Tanvir Ahmed', 4, 'Good fabric, a little long for me. Delivery was quick.', 'whatsapp', true, true, false], ['Sabbir H.', 5, 'Second time buying, same quality. The navy is exactly like the photo.', 'site', true, false, true], ['Arif', 2, 'Colour faded after 3 washes.', 'site', false, false, false], ['Nayeem', 5, 'Fits perfectly, size chart was right.', 'messenger', true, true, false]];
  extra.forEach(function(e, i){ base.push({id:'rvx' + i, product:DB.products[(i * 7 + 2) % DB.products.length].id, name:e[0], rating:e[1], text:e[2], source:e[3], verified:e[4], photo:e[5], pending:!e[6] && i !== 1, hidden:false, at:a2dk(Date.now() - (i + 1) * A2.D)}); }); x.revs = base; } return x.revs; }
